-- The sheet's grace days: when its today moves past an open period's to-date by more than these, the period closes
-- itself. Not dated; null means off.
ALTER TABLE sheet ADD COLUMN grace_days INT;
-- The sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim opened is
-- numbered within its period (<period>-<n>), or X-<n> in no period. Null (blank) means off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number, and the number a correction names, are now text: a sheet-wide 1, 2, ... or P1-1, X-1, ...
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(255);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(255);
-- The last number given out in each period's sequence on a sheet (keyed by period name, or X for no period).
CREATE TABLE claim_number_sequence (
    sheet_id VARCHAR(100) NOT NULL,
    sequence_key VARCHAR(255) NOT NULL,
    last_number BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, sequence_key)
);

    /** The policy date: a claim dated before it rounds half up, one on or after it half to even; null: the today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** From this date (on the sheet's today) a claim opened is numbered within its period; null: off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** Days past an open period's to-date after which a change of today closes it; null: off. Not dated. */
    @Column(name = "grace_days")
    private Integer graceDays;

    /** Whether a steward archived the sheet: everything stays visible and every change is refused. */
    @Column(name = "archived", nullable = false)
    private boolean archived;

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    public Integer getGraceDays() {
        return graceDays;
    }

    public void setGraceDays(Integer graceDays) {
        this.graceDays = graceDays;
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }

    /** Whether a claim opened now is numbered within its period: the setting is a date and today is on or after it. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

        return roles.isViewer(id, user);
    }

    public Sheet get(String id) {
        return sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
    }

    /** The sheet's today: use it for every date-dependent decision and default date. */
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseThrow(() -> new SheetNotFoundException(id));
    }

    /** Whether the sheet is archived: every change to it is refused. A sheet not started yet is not. */
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

